display.text:
import { expect, test } from "bun:test";
import { canaryGreeting } from "./canary";

test("greets Ada", () => {
  expect(canaryGreeting("Ada")).toBe("Hello, Ada!");
});

test("greets an empty name", () => {
  expect(canaryGreeting("")).toBe("Hello, !");
});

